#! /bin/sh
# Fetch the fonts the build consumes but git does not track:
#
#   1. The Noto CJK SC source fonts that (cjk-fonts) subsets from.
#   2. The Inria Sans/Serif webfonts and their @font-face sheet from
#      the Google Fonts css2 API. fonts/inria.css is regenerated by
#      rewriting the sheet's URLs to local paths and re-appending the
#      hand-written Inria Dash faces, whose files are located in the
#      sheet by family, style, weight, and latin subset.
#
# Noto CJK, Inria Sans, and Inria Serif are all SIL OFL 1.1; the
# license files ship alongside the webfonts in fonts/.
set -e
cd "$(dirname "$0")"

# --- 1. CJK source fonts --------------------------------------------
mkdir -p fonts-src
base=https://raw.githubusercontent.com/notofonts/noto-cjk/main
for path in \
  Serif/OTF/SimplifiedChinese/NotoSerifCJKsc-Light.otf \
  Serif/OTF/SimplifiedChinese/NotoSerifCJKsc-Regular.otf \
  Serif/OTF/SimplifiedChinese/NotoSerifCJKsc-Bold.otf \
  Sans/OTF/SimplifiedChinese/NotoSansCJKsc-Regular.otf
do
  name=$(basename "$path")
  if [ -f "fonts-src/$name" ]; then
    echo "have $name"
  else
    echo "fetching $path"
    curl --fail --silent --location --show-error \
      -o "fonts-src/$name.part" "$base/$path"
    mv "fonts-src/$name.part" "fonts-src/$name"
  fi
done

# --- 2. Inria webfonts -----------------------------------------------
# A woff2-capable user agent makes the css2 API serve woff2 split by
# unicode subset; the hashed file names are stable per font version.
mkdir -p fonts
ua="Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
api="https://fonts.googleapis.com/css2?family=Inria+Sans:wght@300;400;700&family=Inria+Serif:ital,wght@0,300;0,400;0,700;1,400;1,700&display=swap"
sheet=fonts/.inria.part.css
curl --fail --silent --location --show-error -A "$ua" -o "$sheet" "$api"

# Inria Dash copies the serif 400 latin files, located by attributes.
dash_serif=$(awk -v RS='}' '/Inria Serif/ && /font-style: normal/ && /font-weight: 400/ && /U\+0000-00FF/ { match($0, /url\(https:[^)]*\)/); print substr($0, RSTART + 4, RLENGTH - 5); exit }' "$sheet")
dash_italic=$(awk -v RS='}' '/Inria Serif/ && /font-style: italic/ && /font-weight: 400/ && /U\+0000-00FF/ { match($0, /url\(https:[^)]*\)/); print substr($0, RSTART + 4, RLENGTH - 5); exit }' "$sheet")
if [ -z "$dash_serif" ] || [ -z "$dash_italic" ]; then
  echo "could not locate Inria Serif 400 latin files in the css2 sheet" >&2
  exit 1
fi

sed -n 's/.*url(\(https:[^)]*\.woff2\)).*/\1/p' "$sheet" | sort -u |
while IFS= read -r url; do
  name=${url##*/}
  if [ -f "fonts/$name" ]; then
    echo "have $name"
  else
    echo "fetching $name"
    curl --fail --silent --location --show-error -o "fonts/.$name.part" "$url"
    mv "fonts/.$name.part" "fonts/$name"
  fi
done

{
  sed 's#url(https://[^)]*/\([^/]*\.woff2\))#url(/fonts/\1)#g' "$sheet"
  cat <<EOF

/* 中文语境的破折号(——)由 CJK 字体全宽连排;英文语境(语言 lane)需要西文字形,
   故复制 serif 的 latin 面为 Inria Dash,只认 U+2014-2015,由 style.css 的
   [lang="en"] 字体栈置前。 */
@font-face {
  font-family: 'Inria Dash';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(/fonts/${dash_serif##*/}) format('woff2');
  unicode-range: U+2014-2015;
}
@font-face {
  font-family: 'Inria Dash';
  font-style: italic;
  font-weight: 400;
  font-display: swap;
  src: url(/fonts/${dash_italic##*/}) format('woff2');
  unicode-range: U+2014-2015;
}
EOF
} > fonts/inria.css
rm -f "$sheet"

# Drop webfonts the regenerated sheet no longer references (the hash
# names change when Google bumps the font version).
for f in fonts/*.woff2; do
  [ -e "$f" ] || continue
  name=${f##*/}
  grep -q "/fonts/$name" fonts/inria.css || {
    echo "removing stale $name"
    rm "$f"
  }
done
